import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { Suspense } from "react";
import HotelList from "./hotel-list";
import SearchSummary from "./search-summary/search-summary";

// import Page from "@/components/search-page/page";
// import getCities from "@/services/tour-category-pages/getCities";

export const dynamicParams = true;
export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Search Results - TravelShop Booking",
  description:
    "Search for tours, destinations and activities in TravelShop Booking website!",
  robots: "noindex",
  alternates: {
    canonical: "https://travelshopbooking.com/",
  },
};

export default async function SearchPage({
  searchParams,
}: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  const sp = await searchParams;
  const term = Array.isArray(sp.term) ? sp.term[0] : sp.term;

  if (!term || !term.trim()) return notFound();

  /* Old tours search, restore when needed:
  const cities = await getCities(0);
  return (
    <Page
      params={{
        cities: cities.data.map((item: any) => ({
          pageTitle: item.breadcrumbTitle,
          pageUrl: `/${item.pageUrl}`,
          locationId: item.paramLocationId,
        })),
      }}
      term={term}
    />
  );
  */

  // useSearchParams() inside HotelList needs a Suspense boundary
  return (
    <main>
<Suspense fallback={null}>
  <SearchSummary />
      <HotelList />
    </Suspense>
    </main>
    
  );
}